public class Solution 
{
    public IList<IList<string>> SolveNQueens(int n)
    {
        IList<IList<string>> result = new List<IList<string>>();
        List<char[]> field = new List<char[]>(n);
        for (int i = 0; i < n; i++)
        {
            var array = new char[n];
            for (int j = 0; j < n; j++)
                array[j] = '.';
            field.Add(array);
        }

        Next(
            field,
            0,
            0,
            0,
            new List<int[]>(n),
            new HashSet<int>(),
            new HashSet<int>(),
            result);

        return result;
    }

    private static void Next(
        List<char[]> field,
        int indexI,
        int indexJ,
        int numberOfQueens,
        List<int[]> previousQueenPositions,
        HashSet<int> prohibitedRows,
        HashSet<int> prohibitedColumns,
        IList<IList<string>> result)
    {
        int needQueenMax = field.Count;

        if (numberOfQueens == needQueenMax)
        {
            result.Add(ToStringList(field));
            return;
        }

        for (int i = indexI; i < field.Count; i++)
        {
            if (prohibitedRows.Contains(i))
                continue;
            int j = 0;
            if (i == indexI)
                j = indexJ;
            for (; j < field[i].Length; j++)
            {
                if (prohibitedColumns.Contains(j))
                    continue;
                bool isForbidden = false;
                foreach (var previousQueenPosition in previousQueenPositions)
                {
                    int r1 = previousQueenPosition[0];
                    int c1 = previousQueenPosition[1];
                    //Check if they diagonally intersect
                    if (Math.Abs(r1 - i) == Math.Abs(c1 - j))
                    {
                        isForbidden = true;
                        break;
                    }
                }
                if (isForbidden)
                    continue;

                prohibitedRows.Add(i);
                prohibitedColumns.Add(j);
                field[i][j] = 'Q';
                var list = new int[2]{i,j};
                previousQueenPositions.Add(list);
                Next(
                    field,
                    i,
                    j,
                    numberOfQueens + 1,
                    previousQueenPositions,
                    prohibitedRows,
                    prohibitedColumns,
                    result);

                previousQueenPositions.Remove(list);
                field[i][j] = '.';
                prohibitedRows.Remove(i);
                prohibitedColumns.Remove(j);
            }
        }
    }

    private static List<string> ToStringList(List<char[]> list)
    {
        var newList = new List<string>(list.Count);
        foreach (var item in list)
        {
            newList.Add(new string(item));
        }
        return newList;
    }
}

