public class TheMostOptimalSolution {
    private static void PlaceQueen(
        IList<IList<string>> ans,
        char[][] tans,
        int n,
        bool[] ld,
        bool[] rd,
        bool[] col,
        int i){
        if(i==n){
            List<string> temp=new List<string>();
            for(int k=0;k<n;k++) temp.Add(new string(tans[k]));
            ans.Add(temp);
            return;
        }
        for(int j=0;j<n;j++){
            if(col[j] || ld[n-1+i-j] || rd[i+j])
                continue;

            col[j]=true;
            ld[n-1+i-j]=true;
            rd[i+j]=true;
            tans[i][j]='Q';

            PlaceQueen(ans,tans,n,ld,rd,col,i+1);

            col[j]=false;
            ld[n-1+i-j]=false;
            rd[i+j]=false;
            tans[i][j]='.';
        }
    }
    public IList<IList<string>> SolveNQueens(int n) {
        IList<IList<string>> ans = new List<IList<string>>();
        char[][] tans = new char[n][];
        for (int i = 0; i < n; i++)
            tans[i] = new string('.', n).ToCharArray();

        bool[] ld = new bool[2 * n - 1];
        bool[] rd = new bool[2 * n - 1];
        bool[] col = new bool[n];
        PlaceQueen(ans, tans, n, ld, rd, col, 0);
        return ans;
    }
}